# Verify the pattern once more
def get_pattern():
    """Pattern coordinates for each 4x5 band"""
    pattern = [(0,1), (0,2), (1,2), (2,0), (2,1), (2,2), (2,3), (3,1)]
    return pattern

# Get colors by row band from test input
def get_colors_by_row_band(grid):
    colors = {}
    num_rows, num_cols = len(grid), len(grid[0])

    for r in range(num_rows):
        for c in range(num_cols):
            val = grid[r][c]
            if val in [1, 2, 3, 4, 6, 7]:  # colored cells
                # Determine row band (0-4), col band (0-4)
                row_sep = [4, 9, 14, 19]
                col_sep = [4, 9, 14, 19]

                # Find which band this cell is in
                tr = 0
                for i, sep_row in enumerate(row_sep):
                    if r < sep_row:
                        tr = i
                        break
                else:
                    tr = i + 1 if i < 4 else 4  # row band 4 for r >= 19
                    if r >= len(row_sep):
                        tr = 4

                tc = 0
                for i, sep_col in enumerate(col_sep):
                    if c < sep_col:
                        tc = i
                        break
                else:
                    tc = i + 1 if i < 4 else 4  # col band 4 for c >= 19

                # Store color by (row_band, col_band)
                if tc not in colors:
                    colors[tc] = {}
                if tr not in colors[tc]:
                    colors[tc][tr] = []
                colors[tc][tr].append(val)

    # Aggregate by row band: pick dominant color from column band 0 (leftmost)
    rband_colors = {}
    for r in range(5):
        # Find dominant color in the first non-empty col band
        for tc in range(5):
            if r in colors.get(tc, {}):
                rband_colors[r] = colors[tc][r][0]  # First color found
                break
    return rband_colors

# Load test input
